				return fmt.Errorf("failed to parse commented schedule HTML: %w", err)
			}
			table = innerDoc.Find("table#schedule")
		}
	}

	if table.Length() == 0 {
		log.Printf("No schedule table found for %s %d.", month, season)
		return nil
	}

